package store

import (
	"errors"
	"testing"
)

// A deleted reminder must come back as ErrNotFound, never as a nil
// reminder with a nil error.
func TestGetDeletedReturnsNotFound(t *testing.T) {
	s := newStore()
	r := s.Create("u1", "water the plants", t0.Add(time.Hour), nil)
	if err := s.Delete(r.ID); err != nil {
		t.Fatal(err)
	}
	got, err := s.Get(r.ID)
	if !errors.Is(err, ErrNotFound) {
		t.Fatalf("Get(deleted) error = %v, want ErrNotFound", err)
	}
	if got != nil {
		t.Errorf("Get(deleted) = %+v, want nil", got)
	}
}

package notify

import (
	"log/slog"
	"testing"
	"time"

	"example.com/remind/store"
)

// Stop must be safe to call more than once; a second call used to panic
// with "close of closed channel".
func TestStopTwice(t *testing.T) {
	d := NewDispatcher(store.New(time.Now), slog.New(slog.DiscardHandler), time.Now)
	d.Stop()
	defer func() {
		if r := recover(); r != nil {
			t.Fatalf("second Stop panicked: %v", r)
		}
	}()
	d.Stop()
}

package auth

import "testing"

// A header with the scheme but no token must be rejected, not panic.
func TestParseBearerNoToken(t *testing.T) {
	for _, h := range []string{"Bearer", "Bearer ", "", "Basic abc"} {
		if tok, ok := parseBearer(h); ok && tok == "" {
			t.Errorf("parseBearer(%q) = %q, true; want rejection", h, tok)
		}
	}
	if _, ok := parseBearer("Bearer"); ok {
		t.Error(`parseBearer("Bearer") accepted a header with no token`)
	}
}

